insert into regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, file_size_kb, download_url) values ('dgms-tech-circular-06-2026-accurate-annual-returns', 'DGMS (Tech) Circular 06 of 2026 — Submission of accurate and complete Annual Returns', 'dgms_circular', 'Addressed to owners, agents and managers of all coal, metalliferous and oil mines. Scrutiny of the Annual Returns submitted by mine managements found many to be incomplete, incorrect or internally inconsistent, which degrades the national mines database and frustrates meaningful statistical analysis. The circular sets out the common discrepancies found — among them an incorrect or incomplete owner name and abbreviated company names — and requires managements to submit accurate and complete returns, since DGMS relies on this data to monitor safety and health performance, analyse accident and occupational-disease trends and target regulatory action.', 'DGMS (Tech) Circular No. CMC/2026/06', 'DGMS', '2026-08-12', 'in_force', null, 'https://www.dgms.gov.in/writereaddata/UploadFile/CircularNo6_14082026.pdf', 'CircularNo6_14082026.pdf', 3, 230, true, false, 701, 'https://docs.mangalamcoal.com/regs/dgms-tech-circular-06-2026-accurate-annual-returns.pdf')
  on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, file_size_kb = excluded.file_size_kb, download_url = excluded.download_url;
